    input = sys.stdin.read().split()
    idx = 0
    n = int(input[idx])
    m = int(input[idx + 1])
    idx += 2
    edges = []
    for _ in range(m):
        a = int(input[idx])
        b = int(input[idx + 1])
        edges.append((a, b))
        idx += 2

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    visited = [False] * (n + 1)
    directions = {}

    def dfs(node, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if (node, neighbor) not in directions and (neighbor, node) not in directions:
                    directions[(node, neighbor)] = 1
                dfs(neighbor, node)
            elif neighbor != parent:
                if (node, neighbor) in directions:
                    if directions[(node, neighbor)] == 1:
                        directions[(node, neighbor)] = -1
                elif (neighbor, node) in directions:
                    if directions[(neighbor, node)] == 1:
                        directions[(neighbor, node)] = -1

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1)

    result = []
    for a, b in edges:
        if (a, b) in directions and directions[(a, b)] == 1:
            result.append((a, b))
        elif (b, a) in directions and directions[(b, a)] == 1:
            result.append((b, a))
        else:
            result.append((a, b))

    while len(result) < n:
        for i in range(1, n + 1):
            if len(result) >= n:
                break
            for j in range(1, n + 1):
                if i != j and (i, j) not in directions and (j, i) not in directions:
                    result.append((i, j))
                    directions[(i, j)] = 1
